/**
 * Settings Page - User settings and preferences
 */

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useTheme } from '../../context/ThemeContext';
import { useLanguage } from '../../context/LanguageContext';
import { authService } from '../../services';

const Settings = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { theme, toggleTheme, isDark } = useTheme();
  const { language, setLanguage, t } = useLanguage();
  const [notifications, setNotifications] = useState({
    email: true,
    push: false,
    updates: true,
  });
  const [autoBackup, setAutoBackup] = useState(true);
  const [privacy, setPrivacy] = useState({
    dataSharing: true,
    downloadHistory: true,
  });
  const [showEmailModal, setShowEmailModal] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [emailForm, setEmailForm] = useState({ newEmail: '', password: '' });
  const [passwordForm, setPasswordForm] = useState({ currentPassword: '', newPassword: '', confirmPassword: '' });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleNotificationChange = (key) => {
    setNotifications(prev => ({
      ...prev,
      [key]: !prev[key]
    }));
  };

  const handlePrivacyChange = (key) => {
    setPrivacy(prev => ({
      ...prev,
      [key]: !prev[key]
    }));
  };

  const handleLanguageChange = (newLanguage) => {
    setLanguage(newLanguage);
  };

  const handleEmailChange = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);

    try {
      if (!emailForm.newEmail || !emailForm.password) {
        setError('Please fill in all fields');
        setLoading(false);
        return;
      }

      if (!emailForm.newEmail.includes('@')) {
        setError('Please enter a valid email address');
        setLoading(false);
        return;
      }

      await authService.changeEmail(emailForm.newEmail, emailForm.password);
      setSuccess('Email changed successfully!');
      setTimeout(() => {
        setShowEmailModal(false);
        setEmailForm({ newEmail: '', password: '' });
        setSuccess('');
        // Refresh user data
        window.location.reload();
      }, 1500);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to change email. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handlePasswordChange = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);

    try {
      if (!passwordForm.currentPassword || !passwordForm.newPassword || !passwordForm.confirmPassword) {
        setError('Please fill in all fields');
        setLoading(false);
        return;
      }

      if (passwordForm.newPassword !== passwordForm.confirmPassword) {
        setError('New passwords do not match');
        setLoading(false);
        return;
      }

      if (passwordForm.newPassword.length < 6) {
        setError('Password must be at least 6 characters long');
        setLoading(false);
        return;
      }

      await authService.changePassword(passwordForm.currentPassword, passwordForm.newPassword);
      setSuccess('Password changed successfully!');
      setTimeout(() => {
        setShowPasswordModal(false);
        setPasswordForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
        setSuccess('');
      }, 1500);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to change password. Please check your current password.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="settings-page">
      <div className="settings-page-header">
        <button className="settings-back-btn" onClick={() => navigate('/dashboard')}>
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
            <path d="M20 11H7.83L13.42 5.41L12 4L4 12L12 20L13.41 18.59L7.83 13H20V11Z" fill="currentColor"/>
          </svg>
          <span>{t('backToDashboard')}</span>
        </button>
        <div className="settings-page-title">
          <h1>{t('settings')}</h1>
          <p>{t('manageAccount')}</p>
        </div>
      </div>

      <div className="settings-content">
        {/* Account Section */}
        <div className="settings-section">
          <h2 className="settings-section-title">{t('account')}</h2>
          <div className="settings-item">
            <div className="settings-item-info">
              <h3>{t('email')}</h3>
              <p>{user?.email || 'Not available'}</p>
            </div>
            <button 
              className="settings-btn-secondary"
              onClick={() => {
                setShowEmailModal(true);
                setError('');
                setSuccess('');
                setEmailForm({ newEmail: '', password: '' });
              }}
            >
              {t('change')}
            </button>
          </div>
          <div className="settings-item">
            <div className="settings-item-info">
              <h3>{t('password')}</h3>
              <p>{t('lastChanged')}</p>
            </div>
            <button 
              className="settings-btn-secondary"
              onClick={() => {
                setShowPasswordModal(true);
                setError('');
                setSuccess('');
                setPasswordForm({ currentPassword: '', newPassword: '', confirmPassword: '' });
              }}
            >
              {t('change')}
            </button>
          </div>
        </div>

        {/* Appearance Section */}
        <div className="settings-section">
          <h2 className="settings-section-title">{t('appearance')}</h2>
          <div className="settings-item">
            <div className="settings-item-info">
              <h3>{t('theme')}</h3>
              <p>{t('chooseTheme')}</p>
            </div>
            <button 
              className="settings-btn-secondary"
              onClick={toggleTheme}
            >
              {isDark ? 'Dark' : 'Light'}
            </button>
          </div>
        </div>

        {/* Notifications Section */}
        <div className="settings-section">
          <h2 className="settings-section-title">Notifications</h2>
          <div className="settings-item">
            <div className="settings-item-info">
              <h3>Email Notifications</h3>
              <p>Receive notifications via email</p>
            </div>
            <label className="settings-toggle">
              <input
                type="checkbox"
                checked={notifications.email}
                onChange={() => handleNotificationChange('email')}
              />
              <span className="settings-toggle-slider"></span>
            </label>
          </div>
          <div className="settings-item">
            <div className="settings-item-info">
              <h3>Push Notifications</h3>
              <p>Receive push notifications</p>
            </div>
            <label className="settings-toggle">
              <input
                type="checkbox"
                checked={notifications.push}
                onChange={() => handleNotificationChange('push')}
              />
              <span className="settings-toggle-slider"></span>
            </label>
          </div>
          <div className="settings-item">
            <div className="settings-item-info">
              <h3>Product Updates</h3>
              <p>Get notified about new features and updates</p>
            </div>
            <label className="settings-toggle">
              <input
                type="checkbox"
                checked={notifications.updates}
                onChange={() => handleNotificationChange('updates')}
              />
              <span className="settings-toggle-slider"></span>
            </label>
          </div>
        </div>

        {/* General Section */}
        <div className="settings-section">
          <h2 className="settings-section-title">General</h2>
          <div className="settings-item">
            <div className="settings-item-info">
              <h3>Language</h3>
              <p>Select your preferred language</p>
            </div>
            <select 
              className="settings-select"
              value={language}
              onChange={(e) => setLanguage(e.target.value)}
            >
              <option value="en">English</option>
              <option value="es">Spanish</option>
              <option value="fr">French</option>
              <option value="de">German</option>
            </select>
          </div>
          <div className="settings-item">
            <div className="settings-item-info">
              <h3>Auto Backup</h3>
              <p>Automatically backup your files</p>
            </div>
            <label className="settings-toggle">
              <input
                type="checkbox"
                checked={autoBackup}
                onChange={() => setAutoBackup(!autoBackup)}
              />
              <span className="settings-toggle-slider"></span>
            </label>
          </div>
        </div>

        {/* Privacy Section */}
        <div className="settings-section">
          <h2 className="settings-section-title">Privacy</h2>
          <div className="settings-item">
            <div className="settings-item-info">
              <h3>Data Sharing</h3>
              <p>Help improve our service by sharing usage data</p>
            </div>
            <label className="settings-toggle">
              <input 
                type="checkbox" 
                checked={privacy.dataSharing}
                onChange={() => handlePrivacyChange('dataSharing')}
              />
              <span className="settings-toggle-slider"></span>
            </label>
          </div>
          <div className="settings-item">
            <div className="settings-item-info">
              <h3>Download History</h3>
              <p>Keep track of your download history</p>
            </div>
            <label className="settings-toggle">
              <input 
                type="checkbox" 
                checked={privacy.downloadHistory}
                onChange={() => handlePrivacyChange('downloadHistory')}
              />
              <span className="settings-toggle-slider"></span>
            </label>
          </div>
        </div>
      </div>

      {/* Email Change Modal */}
      {showEmailModal && (
        <div className="settings-modal-overlay" onClick={() => setShowEmailModal(false)}>
          <div className="settings-modal" onClick={(e) => e.stopPropagation()}>
            <div className="settings-modal-header">
              <h2>Change Email</h2>
              <button 
                className="settings-modal-close"
                onClick={() => setShowEmailModal(false)}
              >
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                  <path d="M19 6.41L17.59 5L12 10.59L6.41 5L5 6.41L10.59 12L5 17.59L6.41 19L12 13.41L17.59 19L19 17.59L13.41 12L19 6.41Z" fill="currentColor"/>
                </svg>
              </button>
            </div>
            <div className="settings-modal-content">
              <p>Email change functionality will be available soon.</p>
              <button 
                className="settings-btn-primary"
                onClick={() => setShowEmailModal(false)}
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Password Change Modal */}
      {showPasswordModal && (
        <div className="settings-modal-overlay" onClick={() => setShowPasswordModal(false)}>
          <div className="settings-modal" onClick={(e) => e.stopPropagation()}>
            <div className="settings-modal-header">
              <h2>Change Password</h2>
              <button 
                className="settings-modal-close"
                onClick={() => setShowPasswordModal(false)}
              >
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                  <path d="M19 6.41L17.59 5L12 10.59L6.41 5L5 6.41L10.59 12L5 17.59L6.41 19L12 13.41L17.59 19L19 17.59L13.41 12L19 6.41Z" fill="currentColor"/>
                </svg>
              </button>
            </div>
            <div className="settings-modal-content">
              <p>Password change functionality will be available soon.</p>
              <button 
                className="settings-btn-primary"
                onClick={() => setShowPasswordModal(false)}
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Settings;
